from __future__ import annotations

import sys

import torch
import helion
import helion.language as hl

from loom import LoomKernel
from loom.loom_utils.kernel_size import resolve_kernel_shape_args
from helion_mlir.custom_op import broadcast  # noqa: F401  (registers the op)


def _k0_gemm(lhs: torch.Tensor, w0: torch.Tensor, w1: torch.Tensor) -> tuple[torch.Tensor, ...]:
    t, k = lhs.size()
    _, n = w0.size()
    out_matmul_36 = torch.empty([t, n], dtype=torch.float16, device=lhs.device)
    out_matmul_48 = torch.empty([t, n], dtype=torch.float16, device=lhs.device)
    for tile_t, tile_n in hl.tile([t, n]):
        acc_matmul_36 = hl.zeros([tile_t, tile_n], dtype=torch.float16)
        acc_matmul_48 = hl.zeros([tile_t, tile_n], dtype=torch.float16)
        for tile_k in hl.tile(k):
            xt = lhs[tile_t, tile_k]
            acc_matmul_36 = hl.dot(xt, w0[tile_k, tile_n], acc=acc_matmul_36)
            acc_matmul_48 = hl.dot(xt, w1[tile_k, tile_n], acc=acc_matmul_48)
        out_matmul_36[tile_t, tile_n] = acc_matmul_36
        out_matmul_48[tile_t, tile_n] = acc_matmul_48
    return out_matmul_36, out_matmul_48


class K0Gemm(LoomKernel):
    """Loom entry point for kernel ``k0_gemm``."""

    kernel_name = "k0_gemm"
    assume_divisible: bool = True

    ARG_SHAPES = [('lhs', [512, 512]), ('w0', [512, 1024]), ('w1', [512, 1024])]
    CONSTEXPRS = []
    TILES = {'tile_t': 128, 'tile_n': 64, 'tile_k': 256}

    kernel = helion.kernel(
        static_shapes=False,
        autotune_config_overrides={
            "range_unroll_factors": [0, 0],
            "range_num_stages": [0, 0],
        },
    )(_k0_gemm)

    def __init__(self, shape: dict[str, int] | None = None) -> None:
        if shape:
            raise SystemExit("generated kernels have fixed shapes; regenerate with torch-helion instead")

    @classmethod
    def bind_args(cls) -> tuple:
        args = [torch.empty(shape, dtype=torch.float16) for _, shape in cls.ARG_SHAPES]
        return tuple(args + [v for _, v in cls.CONSTEXPRS])


if __name__ == "__main__":
    try:
        shape, normalized_argv = resolve_kernel_shape_args(sys.argv)
    except ValueError as exc:
        raise SystemExit(str(exc)) from exc

    sys.argv = normalized_argv
